  out = { verdict: 'NEEDS REWORK', parse_ok: false, rework_class_raw: _rawClass,
    parse_error: txt ? 'no valid JSON object with a "verdict" key in the gate model output'
                     : 'empty/unreadable gate model response',
    blocking_items: [{ item: 'gate_output_unparsed', severity: 'BLOCKING',
      detail: 'FAIL-CLOSED: a PARSER event, not a judgment on the memo. The gate model replied in a shape the parser could not read. Inspect Stage 4 raw output in n8n Executions; if it is a transient formatting flake, simply re-run the ticker.' }],
    raw_head: txt.slice(0, 300) };
}
// v4.2.39 control (3): gate_major_count is VISIBLE but NEVER escalates. A rule of the form
// "N MAJOR -> block" is forbidden: it would gate the same prose twice on two layers (the very
// mechanism #18 is about). The count travels to RESULT and the report as an observable only.
const _gm = Array.isArray(out.major_items) ? out.major_items.length : 0;
const _gn = Array.isArray(out.minor_items) ? out.minor_items.length : 0;

return [{ json: Object.assign({}, out, { audit_text: txt,
  gate_major_count: _gm, gate_minor_count: _gn,
  chat_id: $('Eligibility').first().json.chat_id, ticker: $('Eligibility').first().json.ticker,
  run_mode: $('Eligibility').first().json.run_mode || 'gated' }) }];

