{{ ($json.blocking_items || []).map(b => '• ' + (b.item || b) + (b.detail ? ' — ' + b.detail : '')).join('\n') || '(no blocking items listed)' }}
{{ $json.parse_ok === false && $json.raw_head ? '\nRAW HEAD: ' + $json.raw_head : '' }}

