DIAG: {{ JSON.stringify($('Growth Enrich').first().json.growth_diag) }}\n\n— rework accounting (control 4): class above + gate items MAJOR={{ $json.gate_major_count == null ? '?' : $json.gate_major_count }}, MINOR={{ $json.gate_minor_count == null ? '?' : $json.gate_minor_count }}. Count these events against completed reports to get rework_rate; the honest per-report cost is nominal / (1 - rework_rate).

parameters.jsCode:
const j = $input.first().json;
let txt='';
try { txt = j.candidates[0].content.parts.map(p=>p.text||'').join(''); } catch(e){}
if(!txt){ try { txt = j.choices[0].message.content; } catch(e){} }
if(!txt) txt = '⚠️ RUNNER_ERROR: Auditor returned no text (raw keys: '+Object.keys(j||{}).join(',')+')';
return [{ json: { audit_claims: txt } }];

const _in = $input.first().json;

function _parseResponse(json){
  if (!json) return { text:'', blockTypes:[], apiError:'empty response object', stopReason:'' };
  if (json.type === 'error' || json.error) {
    const em = (json.error && (json.error.message || JSON.stringify(json.error))) || JSON.stringify(json).slice(0,500);
    return { text:'', blockTypes:[], apiError: em, stopReason:'' };
  }
  let text=''; const blockTypes=[];
  if (Array.isArray(json.content)) {
    for (const block of json.content) {
      if (!block) continue;
      blockTypes.push(block.type || 'unknown');
      if (block.type === 'text' && typeof block.text === 'string') text += block.text;
    }
  }
  return { text, blockTypes, apiError:null, stopReason: json.stop_reason || '' };
}

const { text, blockTypes, apiError, stopReason } = _parseResponse(_in);

let memo_text, memo_ok = true;
if (apiError) {
  memo_text = '\u26a0\ufe0f RUNNER_ERROR: Stage6-Arbiter API call returned an error response: ' + apiError;
  memo_ok = false;
} else if (stopReason === 'max_tokens') {
  memo_text = '\u26a0\ufe0f RUNNER_ERROR: Stage6-Arbiter memo generation TRUNCATED at max_tokens \u2014 memo incomplete; raise the limit or shorten stage2b instructions.';
  memo_ok = false;
} else if (!text || !text.trim()) {
  memo_text = '\u26a0\ufe0f RUNNER_ERROR: Stage6-Arbiter returned no text content block. Block types received: [' + blockTypes.join(', ') + ']. stop_reason=' + (stopReason || '(none)') + '.';
  memo_ok = false;
} else {
  memo_text = text;
}
return [{ json: { memo_text, memo_ok, block_types: blockTypes } }];

// Parse DI — v4.2.12: "LLM does judgment, Python does math" applied to the flagship metric.
// The DI number was the last freely-LLM-written number in the report, and it wobbled in
// production (NFLX 2026-07-17 run #2: the arbiter improvised a PARTIAL weight the formula
// does not contain and corrected itself mid-sentence in the SHIPPED report). The arbiter now
// emits raw counts; the formula runs HERE. The arbiter's own di is kept as a canary.
const t = $('Extract Arbiter').first().json.memo_text || '';
let di=null, di_class='UNPARSED', final_verdict='UNPARSED', flip=null, counts=null, _rung_raw=null;
const blocks=[...t.matchAll(/```json\s*([\s\S]*?)```/gi)].map(m=>m[1]);
for (let i=blocks.length-1;i>=0;i--){ try { const o=JSON.parse(blocks[i]);
  if(o&&(o.di!==undefined||o.disagreement_index!==undefined)){
    di=o.di!==undefined?o.di:o.disagreement_index;
    di_class=o.di_class||o.class||di_class; final_verdict=o.final_verdict||o.verdict||final_verdict;
    flip=(o.flip!==undefined)?o.flip:null;
    counts=(o.counts&&typeof o.counts==='object')?o.counts:null;
    _rung_raw=(o.required_mos_rung_pct!==undefined)?o.required_mos_rung_pct:null; break; } } catch(e){} }
if(di===null){ const m=t.match(/DI\s*[=:]\s*([0-9.]+)/i); if(m) di=parseFloat(m[1]); }

// deterministic recomputation (formula F, verbatim: 3*flip + 1*BLOCKING + 0.5*MAJOR + 2*gps + 1*sign)
let di_llm=di, di_source='llm_unverified', di_divergence=false, di_driver_note=null;
// v4.2.56 (a1): the RUNG is the last freely-LLM-written number here. DI itself has been computed
// since v4.2.12 and correctly caught the arbiter's 6.0-vs-3.0 error on MA 2026-07-24 — but the same
// block carried "required_mos_rung_pct": 30, consistent with the WRONG di and inconsistent with the
// computed one, and nothing recomputed it. A rung decides how far below IV an idea must trade
// before it may be bought: it is a money number, and it was prose.
let rung_llm=null, rung_mismatch=false, rung_signals=[], contract_defect=null;
const _int=(x)=>{ const v=Number(x); return Number.isFinite(v)&&v>=0?v:null; };
// The PUBLISHED GPS is deterministic (RESULT.gps.total). Reading it here rather than trusting the
// arbiter's own "gps_memo" keeps one side of the comparison out of the model's hands entirely.
const _gpsPublished=()=>{ try { const r=$('Run Code').first().json;
  const v=(r&&r.gps&&r.gps.total); return Number.isFinite(Number(v))?Number(v):NaN; } catch(e){ return NaN; } };
if (counts){
  const b=_int(counts.sustained_blocking), mj=_int(counts.sustained_major);
  if (b!==null&&mj!==null){
    const gps=counts.gps_recount_delta_gt15===true?1:0;
    const sgn=counts.icagr_sign_disagreement===true?1:0;
    const fl=(flip===true)?1:0;
    const comp=Math.round((3*fl+1*b+0.5*mj+2*gps+1*sgn)*100)/100;
    di_source='python_from_counts';
    if (di_llm!==null && Math.abs(Number(di_llm)-comp)>0.01) di_divergence=true;
    di=comp;
    di_class=(di>=6)?'CONTESTED':(di>=3?'divergence':'consensus');
    // v4.2.56 (b), operator decision 2026-07-23 finally reaching the code (rule 18): DI is a QUALITY
    // FLAG, not a trade blocker. The rung starts at the base 20% and escalates ONLY on DIRECTIONAL
    // signals — a flipped verdict, a sustained BLOCKING finding, or the two sides disagreeing on the
    // SIGN of the gap to hurdle. Volume of MAJOR items is not direction: MA 2026-07-24 reached
    // CONTESTED on six narrative-label defects with zero BLOCKING and no flip, and that is precisely
    // the case the driver note below was written to describe.
    // JUDGMENT CALL, flagged for review: gps_recount_delta_gt15 is deliberately NOT treated as
    // directional — it is a magnitude disagreement about the score, not about which way the idea
    // points. Including it was not in the mandate and would be my call, not the operator's.
    if (fl===1) rung_signals.push('verdict_flip');
    if (b>0) rung_signals.push('sustained_blocking=' + b);
    if (sgn===1) rung_signals.push('icagr_sign_disagreement');
    // v4.2.56a (architect override of my judgment call): the GPS recount gap IS directional, and I
    // had it half right. Bare magnitude is not direction — but WHICH WAY the recount lands is.
    // Recount BELOW the published score means "quality is worse than the memo claims": a substantive
    // dispute about the idea, and a legitimate reason to demand a deeper discount. Recount ABOVE is a
    // dispute in the safe direction and escalates nothing. Escalate on (published - recount) > 15.
    if (gps===1) {
      const _rc = Number(counts.gps_recount), _pub = _gpsPublished();
      if (Number.isFinite(_rc) && Number.isFinite(_pub)) {
        if ((_pub - _rc) > 15) rung_signals.push('gps_recount_below_published(' + _rc + ' vs ' + _pub + ')');
      } else {
        // Direction unknowable: the arbiter raised the >15 flag but shipped no recount VALUE.
        // Escalating keeps the conservative outcome; naming it keeps the omission from being free.
        // Both properties are needed — the omission must not buy a softer rung, nor pass unseen.
        rung_signals.push('gps_recount_delta_gt15_DIRECTION_UNKNOWN');
        contract_defect = contract_defect || 'CONTRACT_DEFECT_gps_recount_value_missing';
      }
    }
    if (di>=6 && b===0 && fl===0)
      di_driver_note='DI reached CONTESTED purely on MAJOR volume ('+mj+' x 0.5); zero BLOCKING, no flip - review whether the manual-verification list is material before treating trades as blocked. Changing the formula itself (cap / sustained-share) is an operator decision, not an automatic one: CONTESTED is a gate.';
  }
}
// v4.2.56 (a2): the recomputation is CONDITIONAL on the arbiter volunteering `counts`. Without it
// di_source stayed 'llm_unverified' and the model's number passed through in silence — the arbiter's
// oldest attack vector is omission, and here omitting one key disabled the only check on its own
// arithmetic. Absence is now a NAMED contract defect, never a quiet fallback.
if (!counts || di_source!=='python_from_counts') {
  contract_defect = 'CONTRACT_DEFECT_arbiter_counts_missing';
  di_source = 'llm_unverified_CONTRACT_DEFECT';
  di_driver_note = (di_driver_note?di_driver_note+' ':'')
    + 'CONTRACT DEFECT: the arbiter shipped no usable `counts` block, so formula F could not be'
    + ' recomputed and DI=' + (di===null?'?':di) + ' is the model\'s own unverified number.'
    + ' Treat the DI line as UNVERIFIED, not as a measurement.';
}
rung_llm = (_rung_raw!==null && Number.isFinite(Number(_rung_raw))) ? Number(_rung_raw) : null;
const required_mos_rung_pct = rung_signals.length ? 30 : 20;
if (rung_llm!==null && Number.isFinite(rung_llm) && rung_llm!==required_mos_rung_pct) rung_mismatch=true;
const contested = (di!==null&&di>=6)||/CONTESTED/i.test(di_class);
return [{ json: { di, di_class, final_verdict, flip, contested,
  di_llm, di_source, di_divergence, di_driver_note, counts,
  required_mos_rung_pct, rung_llm, rung_mismatch, rung_signals, contract_defect,
  chat_id: $('Eligibility').first().json.chat_id, ticker: $('Eligibility').first().json.ticker } }];

const el = $('Eligibility').first().json;
const ticker=el.ticker, chat_id=el.chat_id, company_title=el.company_title||'';
function safe(node,pick){ try { return pick($(node).first().json)||'[no data]'; } catch(e){ return '[no data]'; } }
const memo   = safe('Build Radar', j=>j.memo_clean);
const radar  = safe('Build Radar', j=>j.radar_md);
let tables = safe('Build Radar', j=>j.tables_md_passthrough);
if (tables === '[no data]') tables = safe('Render Tables', j=>j.tables_md);
if (tables === '[no data]') tables = '⚠️ ASSEMBLY DEFECT: numeric tables were rendered (the memo cites them) but BOTH delivery paths failed at assembly. The numbers remain in section 0 provenance and in the memo quotes. Report this defect - do not treat the run as clean.';
// v4.2.16: FACT PACK custody — prefer the main-line passthrough; the direct long-range
// reference lost section 6 ('[no data]') in BOTH 2026-07-18 control runs while the memo
// was quoting FACT_PACK items on the same page.
let fact = safe('Build Radar', j=>(j.dossier_passthrough||{}).factpack_md);
if (fact === '[no data]') fact = safe('Verify FACT_PACK Entity', j=>j.choices[0].message.content);
if (fact === '[no data]') fact = '⚠️ ASSEMBLY DEFECT: the memo cites FACT_PACK, but both delivery paths (main-line passthrough and direct reference) failed at assembly. Report this defect.';
// v4.2.57a: READ the count, never recompute it. Verify FACT_PACK Entity measures; both assemblers
// print. A renderer that derives what it publishes is a second source of truth for the same fact.
const _fpv = (() => { try { return $('Verify FACT_PACK Entity').first().json._fp_vectors || null; }
  catch (e) { return null; } })();
const fpLine = _fpv
  ? ('FACT_PACK vectors: ' + _fpv.unverified + '/' + _fpv.total + ' [UNVERIFIED] ('
     + Math.round((_fpv.pct || 0) * 100) + '%)'
     + (_fpv.data_questionable
        ? ' | 🟠 data_questionable — most of the qualitative side is absent, not merely thin' : '')
     + ' | threshold ' + Math.round(_fpv.threshold * 100) + '% (' + _fpv.threshold_origin + ')')
  : 'FACT_PACK vectors: [UNVERIFIED] — the counter did not reach assembly, report this defect';
// v4.2.59 — SELF-DOCUMENTATION (operator requirement, 02.08.2026). Printed by the ASSEMBLER from
// constants, never written by a model: a parameter that explains itself in prose the model composed
// is a parameter whose rationale drifts run to run. Each line carries a DATE and an AUTHOR, so a
// reader six months out can tell a ratified decision from an accumulated habit — the same reason
// thresholds now carry PROVISIONAL labels.
const WHY_PARAMS = [
  ['Entry rung 20%',
   'operator decision 23.07 / 02.08.2026: insurance against calculation error. Its price is measured — -16.7% on the entry price ($458 -> $382 on MA). Raised only by directional signals, never by DI class.'],
  ['P/E ceiling 25',
   'architect mandate, CONSERVATIVE lens: insurance against multiple compression. The CENTRAL lens is computed WITHOUT it; the question stays open until the validation matrix (Table 2: this layer is worth +33.8% of IV on MA).'],
  ['Fade to 4% terminal',
   'Graham-Dodd standard: no company outgrows the economy forever. The tail may only be slowed toward terminal, never lifted.'],
  ['Growth base min(3y, 5y)',
   'protection against paying up front for one good stretch: endpoints cannot be flattered by a strong middle. The CENTRAL lens uses the median of annual increments instead.'],
  ['Verdict from the conservative lens',
   'the cost of being wrong is asymmetric in money: overpaying costs capital, a missed idea costs return.'],
];
const whyBlock = ['## Why these parameters', '',
  '*Printed by the assembler from constants — not written by a model. Each line carries its date and author.*', '']
  .concat(WHY_PARAMS.map(p => '- **' + p[0] + '** — ' + p[1])).join('\n');
const sent   = safe('Extract Grok', j=>j.sentiment);
const gate4  = safe('Parse Verdict', j=>j.audit_text);
// v4.2.39 control (3): the gate's MAJOR/MINOR counts are OBSERVABLE in the report but never
// escalate — no "N MAJOR -> block" rule exists or may be added (double-gating the same prose).
const gateMaj = (()=>{ try { return $('Parse Verdict').first().json.gate_major_count; } catch(e){ return null; } })();
const gateMin = (()=>{ try { return $('Parse Verdict').first().json.gate_minor_count; } catch(e){ return null; } })();
const gateCountsLine = (gateMaj==null && gateMin==null) ? ''
  : 'gate items: MAJOR=' + (gateMaj==null?'?':gateMaj) + ', MINOR=' + (gateMin==null?'?':gateMin)
    + ' (observational — the gate blocks ONLY on B1-B9 BLOCKING conditions)';
const claims = safe('Extract Audit', j=>j.audit_claims);
let arb      = safe('Extract Arbiter', j=>j.memo_text);
const edgar  = safe('Eligibility', j=>j._edgar?JSON.stringify(j._edgar,null,2):'[no EDGAR metadata surfaced]');
// v4.2.18: DI arrives via the main line (Collect Usage.di_payload — Parse DI's output on
// full runs, Gated Verdict's on gated ones). The direct $('Parse DI') read is the
// FALLBACK only: on a gated run it THROWS (the node never executed), and long-range
// references are the proven custody failure mode anyway.
let di = null;
try { di = ($('Collect Usage').first().json || {}).di_payload || null; } catch(e) { di = null; }
if (!di) { try { di = $('Parse DI').first().json; } catch(e) { di = null; } }
if (!di) di = { di: null, di_class: 'UNKNOWN', final_verdict: null, flip: false, contested: false,
  di_source: 'di_payload_missing_ASSEMBLY_DEFECT', di_divergence: false,
  di_driver_note: 'ASSEMBLY DEFECT: no DI payload reached Assemble by either path — report this.' };
const date=new Date().toISOString().slice(0,10);
// v4.2.29 (contract v1.6): added_at must be the RUN timestamp supplied explicitly by the writer,
// NOT NOW() at insert time and NOT a DB default (there is none). Fix it here, in the data, once.
const run_ts=new Date().toISOString();
// v4.2.56 (b): "TRADES BLOCKED" removed. The operator decided on 2026-07-23 that DI is a QUALITY
// FLAG, not a trade blocker; the decision reached neither the prompt nor this line, and all three
// MA runs printed the blocker wording verbatim. What gates a buy is the RUNG, which is now computed.
const diLine = 'DI='+(di.di!==null?di.di:'?')+' ['+di.di_class+'] | final: '+di.final_verdict
  +' | rung '+(di.required_mos_rung_pct!=null?di.required_mos_rung_pct+'%':'?')
  +(di.rung_signals&&di.rung_signals.length?' ('+di.rung_signals.join(', ')+')':' (base — no directional signal)')
  +(di.flip?' | ⚠️ VERDICT FLIPPED':'')
  +(di.contested?' | 🔴 CONTESTED (quality flag — review the verification list; NOT a trade block)':'')
  +(di.contract_defect?' | ⛔ '+di.contract_defect:'')
// v4.2.56 (a3): the deterministic value must be visible ON THE SURFACE the reader reads, not
// inferred by comparing a header against the arbiter's prose four screens down. MA 2026-07-24
// shipped `DI=3 [divergence]` in the header and `DI = 6.0 -> CONTESTED / Trades blocked` in body
// section F, and both a reviewer and this chat acted on the prose. Publication surfaces are not
// equal in authority, and that inequality has to be printed where the weaker one is.
if (di.di_divergence === true || di.rung_mismatch === true) {
  const _corr = '> 🔴 **DETERMINISTIC CORRECTION.** Computed from the arbiter\'s own counts: DI='
    + (di.di!==null?di.di:'?') + ' [' + di.di_class + '], required rung '
    + (di.required_mos_rung_pct!=null?di.required_mos_rung_pct+'%':'?')
    + '. The arbiter wrote DI=' + (di.di_llm!==null&&di.di_llm!==undefined?di.di_llm:'?')
    + (di.rung_llm!=null?(', rung '+di.rung_llm+'%'):'')
    + '. **The computed values apply.** Any statement below that contradicts them is the model'
    + ' describing itself, not a measurement.';
  arb = _corr + '\n\n' + String(arb || '')
    .split('\n')
    .map(l => /\bDI\s*[=:]/.test(l) ? l + '\n> ⚠️ superseded — see DETERMINISTIC CORRECTION above (DI='
      + (di.di!==null?di.di:'?') + ', rung ' + (di.required_mos_rung_pct!=null?di.required_mos_rung_pct+'%':'?') + ')' : l)
    .join('\n');
}
const gateLine = gateCountsLine;
// v4.2.12: DI is computed in Python from the arbiter's counts; the arbiter's own number is a canary.
const diExtras = []
  .concat(di.di_source==='llm_unverified' ? ['DI UNVERIFIED - arbiter omitted counts; the printed value is the LLM own arithmetic'] : [])
  .concat(di.di_divergence ? ['DI ARITHMETIC DIVERGENCE - arbiter said '+di.di_llm+', formula over its own counts gives '+di.di+' (the computed value is used)'] : [])
  .concat(di.di_driver_note ? [di.di_driver_note] : []);
const diNotes = diExtras.length ? ('\n> ' + diExtras.map(x=>'⚠️ '+x).join('\n> ')) : '';
// The vector count rides beside DI: both answer "how much of this report is actually supported?"
const fpNotes = '\n> ' + ((_fpv && _fpv.data_questionable) ? '🟠 ' : '') + fpLine;
// ---------- v4.2.5 run cost ----------
// Tokens are facts (each provider's own usage block). Dollars are an ESTIMATE and say so, every
// time, in the same breath as the number. A billing section must never take the report down:
// Cost Ledger runs onError=continueRegularOutput, so this handles its absence as a first-class
// case rather than assuming success.
let costLedger = null;
try { costLedger = $('Cost Ledger').first().json || null; } catch(e) { costLedger = null; }
let costSection, costSummary;
if (!costLedger || costLedger._FALLBACK || !costLedger.rows) {
  costSection = '_Cost ledger unavailable this run (the /cost call failed or did not execute). '
    + 'This is NOT a $0 run — the tokens were spent and the meter was lost._';
  costSummary = 'cost: [UNVERIFIED — ledger unavailable]';
} else {
  const t = costLedger.totals || {}, pt = costLedger.price_table || {};
  const L = [];
  L.push('| Stage | Model | In | Out | Cached rd/wr | Est. USD |');
  L.push('|---|---|---|---|---|---|');
  const fmt = v => (v==null?'—':Number(v).toLocaleString('en-US'));
  for (const r of costLedger.rows) {
    let cost;
    if (r.status === 'not_run')       cost = '_not run_';
    else if (r.status === 'meter_lost') cost = '**meter lost**';
    else if (r.est_cost_usd == null)  cost = '**[UNVERIFIED]**';
    else                              cost = '$' + Number(r.est_cost_usd).toFixed(4);
    L.push('| ' + r.stage + ' | ' + (r.model||'—') + ' | ' + fmt(r.input_tokens) + ' | '
      + fmt(r.output_tokens) + ' | ' + fmt(r.cache_read_tokens) + '/' + fmt(r.cache_write_tokens)
      + ' | ' + cost + ' |');
  }
  L.push('| **TOTAL** |  | **' + fmt(t.input_tokens) + '** | **' + fmt(t.output_tokens)
    + '** |  | **$' + Number(t.est_cost_usd||0).toFixed(4) + (t.est_cost_is_partial?' (PARTIAL)':'') + '** |');
  L.push('');
  L.push('_' + (costLedger._basis||'') + '_');
  if (t.est_cost_is_partial) {
    L.push('');
    L.push('**This total is PARTIAL — the real bill is HIGHER.**');
    if ((t.excluded_unpriced||[]).length)   L.push('- No price in the table, excluded: ' + t.excluded_unpriced.join(', '));
    if ((t.excluded_meter_lost||[]).length) L.push('- Ran but usage unreadable, excluded: ' + t.excluded_meter_lost.join(', '));
    if ((t.understated_incomplete||[]).length) L.push('- Token-only (provider also bills per request): ' + t.understated_incomplete.join(', '));
  }
  const warn = [];
  if (pt.stale) warn.push('price table is ' + pt.age_days + ' days old (>' + pt.stale_after_days + ') — REFRESH IT');
  for (const e of (pt.expiring||[])) warn.push(e.model + ': ' + e.status + ' ' + e.on + ' — ' + e.detail);
  if ((pt.unverified_by_operator||[]).length) warn.push('rates never checked against vendor pages by the operator: ' + pt.unverified_by_operator.join(', '));
  let drift = [];
