// ---------- 2. Scorecard A–H ----------
// blocks may be array, or object keyed by block name (actual Stage2a shape), with a nested
// pinned_ACDF gps_quant dict + named blocks {value, points, source}.
const rawBlocks = gps.blocks || gps.scorecard || gps.detail;
let blocks = [];
if (isObj(rawBlocks) && !Array.isArray(rawBlocks)) {
  for (const [k,v] of Object.entries(rawBlocks)) {
    if (!isObj(v)) continue;
    // v3.1 STRUCTURAL fix (was: key-name regex matching "quant" substring, which false-
    // positived on a flat leaf block literally named "A_quant" -> exploded its {points,value}
    // into garbage rows labeled "points"/"value" instead of one row named "A_quant").
    // Decide LEAF vs WRAPPER by the object's OWN shape, never by its key name.
    const hasOwnScore = (typeof v.points === 'number') || (typeof v.pts === 'number');
    if (hasOwnScore || v.source !== undefined) {
      // LEAF: this IS one scorecard row (whatever its key is called: A_quant, E_moat, ...).
      blocks.push(Object.assign({name:k}, v));
      continue;
    }
    // WRAPPER candidate: a dict whose children look like gps_quant sub-blocks
    // (each child either a plain number score, or an object carrying .pts/.max_quant).
    // 'detail' is a legacy metadata key (raw sub-block detail), not a scored child -- exclude it.
    const childVals = Object.entries(v).filter(([kk])=>kk!=='detail').map(([,sv])=>sv).filter(x => x !== undefined);
    const looksLikeWrapper = childVals.length>0 && childVals.every(sv =>
      typeof sv === 'number' || (isObj(sv) && (isObj(sv.pts) || typeof sv.pts === 'number')));
    if (looksLikeWrapper) {
      for (const [pk,pv] of Object.entries(v)) {
        if (pk === 'detail') continue;
        if (typeof pv === 'number') {
          blocks.push({name:pk, points:pv, max:null, evidence:'deterministic (gps_quant)'});
        } else if (isObj(pv)) {
          const pts = isObj(pv.pts) ? Object.values(pv.pts).reduce((a,x)=>a+(typeof x==='number'?x:0),0) : (pv.points!==undefined?pv.points:null);
          const mx = pv.max_quant!==undefined?pv.max_quant:(pv.max!==undefined?pv.max:null);
          const evb = Object.entries(pv).filter(([kk])=>kk!=='pts'&&kk!=='max'&&kk!=='max_quant')
                        .map(([kk,vv])=>kk+'='+(typeof vv==='number'?(Math.abs(vv)<10?vv.toFixed(3):vv.toFixed(0)):JSON.stringify(vv))).join(', ');
          if (pts!==null) blocks.push({name:'block '+pk, points:pts, max:mx, evidence:evb.slice(0,120)});
        }
      }
      continue;
    }
    // fallback: unknown shape, still render as a single best-effort row rather than drop it.
    blocks.push(Object.assign({name:k}, v));
  }
} else {
  blocks = asArray(rawBlocks);
}
if (blocks.length) {
  H.push('\n### Scorecard');
  H.push(row('Block','Points','Max','Evidence / source'));
  H.push(row('---','---','---','---'));
  // v2.4: de-duplicate blocks representing the SAME logical scorecard block. Stage2a wiring
  // sometimes emits gps_quant BOTH as 'block A' AND flat 'quant_A_quant' -> double count. Canonicalize
  // (strip 'block '/'quant_' prefixes and '_quant' suffix) and keep one row per logical block (the
  // richer one carrying max). Qualitative blocks (A_runway, E_moat, ...) canon differently -> kept.
  (function(){ function _canon(nm){ return String(nm||'').replace(/^block\s+/i,'').replace(/^quant[_ ]/i,'').replace(/_quant$/i,'').trim().toUpperCase(); }
    const _seen={}, _out=[];
    for(const b of blocks){ const c=_canon(b.name||b.block||b._key); if(!c){ _out.push(b); continue; }
      if(_seen[c]){ const pB=(b.points!==undefined?b.points:b.score), pS=(_seen[c].points!==undefined?_seen[c].points:_seen[c].score);
        if(b.max!=null && _seen[c].max==null){ _seen[c].max=b.max; if(_seen[c].name&&/^quant/i.test(_seen[c].name)) _seen[c].name=b.name; } continue; }
      _seen[c]=b; _out.push(b); }
    blocks=_out; })();
  let visibleSum = 0, visibleMax = 0;
  for (const b of blocks) {
    const ev = (b.source||b.evidence||b.detail||b.value||'');
    const pts = (b.points!==undefined?b.points:b.score);
    if (typeof pts === 'number') visibleSum += pts;
    if (typeof b.max === 'number') visibleMax += b.max;
    H.push(row(b.name||b.block||b._key||'?', n(pts,1),
               b.max==null?'—':n(b.max,0),
               (typeof ev==='object'?JSON.stringify(ev):String(ev)).replace(/\|/g,'/').slice(0,140)));
  }
  // v2.3: DETERMINISTIC GPS total = sum of rendered (auditable) blocks. The wiring's gps.total
  // was unreliable (omitted quant blocks -> false GPS_TOTAL_MISMATCH on PLTR/AMZN/FOUR). The
  // headline total is now, by construction, the sum of the visible rows -> always auditable.
  const _wiringTotal = gps.total;
  gps.total = Math.round(visibleSum*10)/10;
  try { if (res && res.gps) res.gps.total = gps.total; } catch(e){}
  // v4.2.2: the denominator is the sum of MEASURABLE sub-blocks, not a nominal 100. gps_quant
  // drops any sub-block whose input is null out of BOTH numerator and denominator -- a data gap
  // is not a failing grade -- so a degraded run reads e.g. 57/88 and says why.
  const _maxShown = (visibleMax>0 ? visibleMax : 100);
  H.push(row('**TOTAL GPS**','**'+n(gps.total,0)+'**','**'+n(_maxShown,0)+'**',
    '= sum of visible blocks (deterministic)'+(_maxShown<100?' — max reduced from 100: sub-blocks with unavailable inputs are [UNVERIFIED], not 0':'')));
  if (_maxShown < 100) H.push('\n**GPS is scored out of '+n(_maxShown,0)+', not 100.** '
    +(100-_maxShown).toFixed(0)+' points of scale were unmeasurable this run — do NOT compare this '
    +'total against a full-scale GPS from another ticker without normalising.');
  if (_wiringTotal!=null && Math.abs(_wiringTotal - gps.total) > 0.6) {
    H.push('\n_note: wiring-reported GPS total was '+n(_wiringTotal,1)+'; authoritative total = sum of visible blocks = '+n(gps.total,1)+' (wiring total discarded — total is deterministic, not a defect)._');
  }
}

