// ---------- 5. Sensitivity ----------
if (res.sensitivity) {
  H.push('\n### Sensitivity — implied CAGR');
  const S = res.sensitivity;
  if (isObj(S) && Array.isArray(S.matrix) && Array.isArray(S.cols) && Array.isArray(S.rows)
      && S.matrix.every(r=>Array.isArray(r))) {
    H.push(row('g \\ PE', ...S.cols.map(c=>n(c,0))));
