    S.matrix.forEach((r,i)=> H.push(row(pct((S.rows[i]||0)*100,1), ...r.map(v=>pct(v)))));
  } else if (isObj(S)) {
    // actual Stage2a shape: flat dict {"g0.75_pe0.8": impliedCAGR, ...} -> pivot to matrix
    const keys = Object.keys(S);
    const parse = k => { const m = k.match(/g([0-9.]+)_pe([0-9.]+)/); return m? {gm:m[1], pm:m[2]} : null; };
    const parsed = keys.map(k=>({k, p:parse(k)})).filter(x=>x.p);
    if (parsed.length) {
      const gms = [...new Set(parsed.map(x=>x.p.gm))];
      const pms = [...new Set(parsed.map(x=>x.p.pm))];
      H.push(row('g× \\ PE×', ...pms));
      H.push(row(...Array(pms.length+1).fill('---')));
      for (const gm of gms) {
        const cells = pms.map(pm=>{ const hit=parsed.find(x=>x.p.gm===gm&&x.p.pm===pm); return hit? pct(S[hit.k]) : '—'; });
        H.push(row(gm, ...cells));
      }
      H.push('\n_g× = multiplier on base growth; PE× = multiplier on base future P/E_');
    } else {
      H.push('```json\n'+JSON.stringify(S,null,1).slice(0,1000)+'\n```');
