// ---------- 6. Bull/Bear ----------
const bb = isObj(res.bull_bear) ? res.bull_bear : {};
const bbTable = isObj(bb.table) ? bb.table : bb;
const bbRows = asArray(bbTable.rows || bb.rows || bb.arguments);
if (bbRows.length) {
  // DETERMINISTIC IDs: assign BL1.. / BR1.. by side in |EI| order, so IDs never depend on 2b's prose.
  // Stage4's ID-based radar check and the RADAR_LINK_REQUIRED list reference THESE ids.
  let blN = 0, brN = 0;
  for (const r of bbRows) {
    if (r.error) { r._id = '—'; continue; }
    r._id = (r.side === 'BULL') ? ('BL' + (++blN)) : ('BR' + (++brN));
  }
  H.push('\n### BULL / BEAR — quantified arguments (sorted by |expected impact|)');
  H.push(row('ID','Side','Argument','P','ΔIV','ΔIV%','Δcagr pp','Expected impact'));
  H.push(row('---','---','---','---','---','---','---','---'));
  for (const r of bbRows) {
    if (r.error) { H.push(row('—','—', (r.label||'')+' (ERROR: '+r.error+')','—','—','—','—','—')); continue; }
    H.push(row(r._id, r.side, (r.label||'').slice(0,55), n(r.probability,2),
      '$'+n(r.delta_iv), pct(r.delta_iv_pct), n(r.delta_implied_cagr_pp,2),
      '$'+n(r.expected_impact)));
  }
  // totals: prefer provided, else derive from rows so the table is never blank
  const sumSide = (side)=> bbRows.filter(r=>r.side===side)
    .reduce((a,r)=>a+(typeof r.expected_impact==='number'?r.expected_impact:0),0);
  const bull_total = (bbTable.bull_total!==undefined)? bbTable.bull_total : sumSide('BULL');
  const bear_total = (bbTable.bear_total!==undefined)? bbTable.bear_total : sumSide('BEAR');
  const net_skew   = (bbTable.net_skew!==undefined)? bbTable.net_skew : (bull_total+bear_total);
  const sum_exp    = (bbTable.sum_expected_impact!==undefined)? bbTable.sum_expected_impact : (bull_total+bear_total);
  H.push(row('**BULL total**','','','','','','**$'+n(bull_total)+'**'));
  H.push(row('**BEAR total**','','','','','','**$'+n(bear_total)+'**'));
  H.push(row('**NET SKEW**','','','','','','**$'+n(net_skew)+'**'));
  // RADAR SKELETON (v2.5): FULLY deterministic ID+driver+suggested-threshold.
  // Root fix for radar_unlinked (BR2 mismatch) and radar_no_threshold: 2b no longer
  // rewrites ID/driver/operator — those are printed here and must be COPIED VERBATIM.
  // 2b only appends a prose ACTION. This removes the two hand-fill error modes entirely.
  const plr = (()=>{ try { return $('Eligibility').first().json || {}; } catch(e){ return {}; } })();
  const num2 = v => (v==null||Number.isNaN(v))?null:(typeof v==='number'?v:null);
  // map an argument label to a concrete metric + operator + number drawn from payload/EVIDENCE
  function suggestThreshold(label, side){
    const L = (label||'').toLowerCase();
    const rs6 = num2(plr.rel_strength_6m);
    const om = (plr.op_margin_series||[]).filter(x=>typeof x==='number');
    const omLast = om.length?om[om.length-1]:null;
    const dil = num2(plr.dilution_cagr);
    const pehm = num2(plr.pe_hist_median);
    const peer = num2(plr.peer_median_pe);
    const sbc = num2(plr.sbc_to_revenue);
    let r;
    // bear.future_pe from scenarios (real compression floor), if present
    let bearPe = null;
    try { const bs = res.scenarios && res.scenarios.bear; const bi = bs && (bs.result||bs.ivc||bs);
          bearPe = bi && (bi.inputs? bi.inputs.future_pe : bs.future_pe); } catch(e){}
    const isBear = (side==='BEAR');
    if (/relative strength|rel str|momentum|price/.test(L) && rs6!=null)
      r={metric:'Relative strength 6m', thr:'<'+(rs6*100).toFixed(1)+'%', where:'price vs SPY'};
    else if (/capex|supercycle|d&d|d&a|fcf|free cash|reinvest/.test(L))
      // capex/FCF risk: monitor capex growth + FCF conversion, NOT P/E (arbiter claim #5 fix)
      r={metric:'Capex YoY / FCF-conv', thr:'>60% (capex YoY) for 2 quarters AND <70% (FCF-conv)', where:'Cash Flow Statement (10-Q)'};
    else if (/margin|profitab/.test(L) && omLast!=null)
      r={metric:'Operating margin', thr:'<'+((omLast-0.02)*100).toFixed(1)+'%', where:'Income Statement (10-Q)'};
    else if (/multiple|re-rat|compress|de-rat|pe |p\/e|valuation|trough/.test(L)){
      // DIRECTION MATTERS: bear = compression -> P/E falls BELOW a floor (<); bull = re-rating -> rises ABOVE (>)
      const anchor = peer||pehm;
      if (isBear) r={metric:'Forward P/E', thr: bearPe?('<'+Number(bearPe).toFixed(0)):(anchor?('<'+(anchor*0.75).toFixed(0)):'<18'), where:'market price / EPS'};
      else r={metric:'Forward P/E', thr: anchor?('>'+(anchor*1.2).toFixed(0)):'>35', where:'market price / EPS'};
    }
    else if (/dilution|sbc|share count|buyback|comp/.test(L))
      r={metric:'SBC/Revenue', thr: sbc!=null?('>'+((sbc+0.02)*100).toFixed(1)+'%'):'>9%', where:'Cash Flow Statement (10-Q)'};
    else if (/ad-tier|ad tier|password|monetiz|arpu|subscriber|paid net|attach/.test(L))
      // v4.2.24 (radar #12b): ad-tier/password-sharing monetization has no single filed KPI but IS
      // falsifiable against reported subscriber-linked revenue growth. Anchor to a measurable filed
      // metric with an operator -- NOT the old '<0 vs base' which named no metric and no base.
      r={metric:'Streaming revenue YoY (ad-tier/monetization proxy)', thr:'<12%', where:'10-Q, revenue by segment / MD&A ARPU commentary'};
    else if (/ad-market|ad market|advertis|cyclical|demand|revenue|datacenter|decel|growth/.test(L))
      r={metric:'Revenue YoY', thr:'<15%', where:'10-Q, segment revenue'};
    else if (/regulat|antitrust|litig|legal|fine|probe|overhang/.test(L))
      r={metric:'Regulatory event', thr:'>1 (formal charge/fine >$1B)', where:'8-K, regulators'};
    else if (/rate|discount|macro|cost of capital/.test(L))
      r={metric:'10Y Treasury', thr:'>+100bp', where:'FRED DGS10'};
    else
      // v4.2.24 (radar #12b). The old default emitted '<0 (deterioration vs base)' for any driver
      // matching no pattern -- a non-falsifiable tripwire (no named metric, no defined base) the
      // auditor correctly stamped MAJOR (NFLX BL1 2026-07-19). A soft threshold is worse than an
      // honest gap: it looks executable but cannot be triggered. Name the driver as needing a
      // sourced numeric KPI and point where one would be filed -- honest gap, not fake tripwire.
      r={metric:('driver: '+(label||'').slice(0,28)+' [needs sourced KPI]'), thr:'no filed numeric KPI this run', where:'10-Q/8-K/earnings release -- set a numeric trigger once a base is sourced'};
    // GUARANTEE: threshold ALWAYS starts with an operator (post-validate the branch output)
    // v4.2.24: do NOT fake an operator onto an honest 'no KPI' gap -- that recreates the soft-
    // threshold defect. Skip the guarantee when the branch reported no numeric KPI; else enforce.
    if (!/no filed numeric KPI/.test(r.thr)) {
      if (!/^\s*(<=|>=|<|>|=)/.test(r.thr)) r.thr = '<'+r.thr.replace(/^[^0-9.\-]*/,'');
      if (!/^\s*(<=|>=|<|>|=)/.test(r.thr)) r.thr = '< '+r.thr;  // last-resort
