  H.push('\n_Σ expected impact = $'+n(sum_exp)+' — a one-factor sensitivity sum (marginal shifts). '
    + (typeof _pmi === 'number'
        ? 'Scenario PWFV − IV' + _legLbl2 + ' = $' + n(_pmi) + ' — joint weighted scenarios, both terms on the verdict leg (RESULT.sensitivity).'
        : 'Scenario PWFV − IV: not published by RESULT for this run.')
