// print. A renderer that derives what it publishes is a second source of truth for the same fact.
const _fpv = (() => { try { return $('Verify FACT_PACK Entity').first().json._fp_vectors || null; }
  catch (e) { return null; } })();
const fpLine = _fpv
  ? ('FACT_PACK vectors: ' + _fpv.unverified + '/' + _fpv.total + ' [UNVERIFIED] ('
     + Math.round((_fpv.pct || 0) * 100) + '%)'
     + (_fpv.data_questionable
        ? ' | 🟠 data_questionable — most of the qualitative side is absent, not merely thin' : '')
     + ' | threshold ' + Math.round(_fpv.threshold * 100) + '% (' + _fpv.threshold_origin + ')')
  : 'FACT_PACK vectors: [UNVERIFIED] — the counter did not reach assembly, report this defect';

const gate=(()=>{ try{return $('Run Scenario Tree (Core-V)').first().json.reverse_anchor_gate||{};}catch(e){return {};} })();
const verdict=cv.verdict || (gate.no_margin_of_safety?'AVOID_SELL':'SPECULATIVE');
const blocking=(cv.blocking_open!=null)?cv.blocking_open:'?';
const sizing=(cv.position_cap_pct!=null)?cv.position_cap_pct:0;
const spec=(cv.spec_conditions_met!=null)?cv.spec_conditions_met:'?';
const date=new Date().toISOString().slice(0,10);
const md=[ '# '+ticker+' — CORE-V (pre-profit / Category-F) — '+date,
 '> Arbiter verdict: '+verdict+' | spec '+spec+'/3 | sizing '+sizing+'% | blocking_open '+blocking,
 '> '+fpLine, '',
 '## 0. EDGAR provenance & cross-check (SEC first-source + sanity gates)', '```json', edgar, '```', '',
 '## 1. Deterministic anchors (scenario_f)', '```json', anchors, '```', '',
 '## 2. Venture memo (Gemini — scenarios, TAM, sizing)', memo, '',
 '## 3. Adversarial audit (GPT — claims: BLOCKING/MAJOR/MINOR)', claims, '',
 '## 4. Arbiter adjudication (Claude — binding verdict)', arb, '',
 '## 5. Growth Fact Pack', fact ].join('\n');
const fname=ticker+'_'+date.replace(/-/g,'')+'_coreV.md';
return [{ json:{ chat_id, ticker, verdict, blocking }, binary:{ data:{ data:Buffer.from(md,'utf8').toString('base64'), mimeType:'text/markdown', fileName:fname } } }];

const SVC='YOUR_PYTHON_SERVICE_URL';
const s = $input.first().json;
const http = this.helpers.httpRequest;
// v2.8: deterministic Form 4 insider transactions (SEC first-source), phase 2 of EDGAR
// integration. Replaces reliance on Perplexity/FACT_PACK prose for insider activity (which
// previously produced an impossible trade: '600 shares for $1,655' = $2.76/share). Price and
// share counts here are exact SEC-reported facts, not inferred from secondary commentary.
let insider_form4 = null;
try {
  insider_form4 = await http({ method:'POST', url:SVC+'/edgar_form4',
    body:{ ticker: s.ticker, lookback_days: 270 }, json:true, timeout:40000 });
} catch(e) {
  insider_form4 = { _errors: { fetch: String(e).slice(0,150) } };
}
return [{ json: Object.assign({}, s, { insider_form4 }) }];

// v3.9 NUMBER AUDIT — deterministic anti-hallucination layer.
// Extracts every material number from the memo prose and matches it against a whitelist built
// from RESULT + GROUND_TRUTH + rendered tables. Python FINDS unsourced numbers; the auditor
// (LLM) then JUDGES severity — instead of one LLM hunting another LLM's inventions by eye.
const memoJ = $('Extract Memo').first().json;
const memo = memoJ.memo_text || '';
const srcBlob = JSON.stringify($('Run Code').first().json) + ' ' +
                JSON.stringify($('Eligibility').first().json) + ' ' +
                (($('Render Tables').first().json||{}).tables_md||'');
// whitelist: every numeric token in the sources, plus scale/format variants the memo may use
const wl = new Set();
function addVariants(x){
  if (!isFinite(x)) return;
  [x, x/1e6, x/1e9, x*100, x/100, x/1e3].forEach(v=>{
    [0,1,2,3].forEach(dp=>wl.add(Number(Math.abs(v)).toFixed(dp)));
  });
}
(srcBlob.match(/-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/g)||[]).forEach(t=>addVariants(parseFloat(t)));
// candidate numbers in the memo: skip years, small ordinals, radar IDs
const out=[]; let total=0;
const sentences = memo.split(/(?<=[.!?])\s+|\n/);
for (const sent of sentences){
  if (sent.includes('[UNVERIFIED]')) continue;              // honestly marked, not a claim
  // negative lookbehind: skip numbers glued to letters (FY26, Q3, BR2) — they are labels;
  // capture the $ / % marker so scale intent survives
  const nums = [];
  const re = /(?<![A-Za-z\d])(\$?\d[\d,]*(?:\.\d+)?%?)/g;
  let mm; while ((mm=re.exec(sent))!==null) nums.push(mm[1]);
  for (const raw of nums){
    const clean = raw.replace(/[$,%]/g,'').replace(/,/g,'');
    const v = parseFloat(clean);
    if (!isFinite(v)) continue;
    if (/^(19|20)\d{2}$/.test(clean)) continue;              // years
    if (!raw.includes('$') && !raw.includes('%') && v<=12 && Number.isInteger(v)) continue; // ordinals/counts
    // bare section-style numbers (6.1, 2.3) without $/% and small: labels, not claims
    if (!raw.includes('$') && !raw.includes('%') && v<=12) continue;
    total++;
    let matched=false;
    for (const dp of [0,1,2,3]){
      if (wl.has(Math.abs(v).toFixed(dp))) { matched=true; break; }
    }
    if (!matched) out.push({value: raw, context: sent.trim().slice(0,140)});
  }
}
let _tables_pass = null; try { _tables_pass = $('Render Tables').first().json.tables_md || null; } catch(e) {}
// v4.2.16 dossier custody: carry spec/factpack/result/accession alongside tables_md.
let _doss_pass = null; try { const _r = $('Render Tables').first().json;
  _doss_pass = { spec_json: _r.spec_json_passthrough || null, factpack_md: _r.factpack_passthrough || null,
    result_json: _r.result_json || null, last_filing_accession: _r.last_filing_accession_passthrough || null };
} catch(e) {}
return [{ json: { memo_numbers_total: total, unmatched_count: out.length,
  unmatched: out.slice(0,25), tables_md_passthrough: _tables_pass, dossier_passthrough: _doss_pass,
  _note: 'unmatched = number in memo prose with NO counterpart in RESULT/GROUND_TRUTH/tables (within rounding & B/M/% scaling). Auditor must trace each: truly unsourced -> MAJOR unsourced_number.' } }];

// v4.2.5 — Collect Usage. Every LLM node here is an httpRequest, so the provider's own `usage`
// block already comes back in the response and, until now, was silently discarded on every run.
// This node only HARVESTS. It computes nothing: prices and arithmetic live in pricing.py, one
// canonical home, covered by the python suite. A price edit must not cost a workflow re-import.
//
// $('Node') THROWS when the node did not execute (e.g. the Core-V branch). That throw is
// information, not an error: "did not run" is a real zero. It must never be confused with
// "ran but we could not read the meter", which is money spent and unmeasured. Two different
// unknowns; pricing.py keeps them apart and so must this.
const STAGES = [
  // v4.2.74: four themed calls, four cost rows. This is the whole reason variant A was chosen over
  // one Code node doing four fetches: money spent inside code is money this ledger cannot see, and
  // the Grok row taught us exactly what an unseen stage looks like in a report.
  ['Stage 1 FP legal',   'perplexity', 'sonar-pro'],
  ['Stage 1 FP compete', 'perplexity', 'sonar-pro'],
  ['Stage 1 FP news',    'perplexity', 'sonar-pro'],
  // The merge buys nothing: a declared zero, checkable exactly like a non-zero row.
  ['Merge FACT_PACK Calls', null, null],
  // v4.2.57, rule 4: Verify FACT_PACK Entity joins the PATH MAP. A zero row is not an absence —
  // it is the claim "this hop is accounted for and costs nothing", and it is checkable exactly
  // like a non-zero one. The token spend stays on Raw, where the tokens are actually bought;
  // moving it to a code node to make a grep come out even would have corrupted honest cost.
  ['Verify FACT_PACK Entity', null, null],
  ['Stage 2a Claude',     'anthropic',  'claude-sonnet-5'],
  ['Stage 3 Grok',        'xai',        'grok-4.5'],
  ['Stage 2b Claude',     'anthropic',  'claude-sonnet-5'],
  ['Stage 4 Gemini',      'gemini',     'gemini-3.1-pro-preview'],
  ['Stage 5 Auditor',     'openai',     'gpt-5.6-sol'],
  ['Stage 6 Arbiter',     'anthropic',  'claude-opus-4-8'],
  ['Core-V Narrative',    'gemini',     'gemini-3.1-pro-preview'],
  ['Core-V Auditor',      'openai',     'gpt-5.6-sol'],
  ['Core-V Arbiter',      'anthropic',  'claude-opus-4-8'],
];

// v4.2.21 METER FIX (BACKLOG D.2). A throw on $(name) meant BOTH "branch did not execute"
// AND "stage ran but the custody reference could not reach it" -- and the two printed the same
// word, "not run". They are different claims: a branch that did not run is genuinely free; a
// stage that ran but whose meter we could not read COST MONEY we failed to measure (pricing.py
// already keeps them apart as not_run vs meter_lost -- it was fed the wrong `ran`). The recurrence
// of the v4.2.8 lesson "zero is not unknown", one level up. So `ran` is no longer decided by the
// throw; it is decided by WHICH PATH and WHICH MODE we are actually on, which is deterministic:
//   - Core-P main line up to here ALWAYS executes Stage 1/2a/2b/4 (gated only trims 5/6). A throw
//     on those is a LOST METER, not a free stage -> ran=true, response=null -> pricing.py: meter_lost.
//   - Stage 5/6 run on `full`, NOT on `gated`. di_payload.di_class==='GATED' -> truly not_run.
//   - Stage 3 Grok is disabled by operator decision -> truly not_run.
//   - Core-V nodes never run on a Core-P execution -> truly not_run.
// di_payload rides the SAME main line (Parse DI on full, Gated Verdict on gated); reading it here
// is one short hop and is the pinned, green custody path -- this fix does NOT touch its shape.
let _diClass = null;
try { _diClass = ($input.first().json || {}).di_class || null; } catch (e) { _diClass = null; }
const _gated = (_diClass === 'GATED');
// Stages that TRULY do not execute on this path/mode (their absence is a real zero, not a lost meter):
const NOT_ON_PATH = new Set(['Stage 3 Grok', 'Core-V Narrative', 'Core-V Auditor', 'Core-V Arbiter']);
if (_gated) { NOT_ON_PATH.add('Stage 5 Auditor'); NOT_ON_PATH.add('Stage 6 Arbiter'); }

const stages = [];
for (const [name, provider, model] of STAGES) {
  let response = null, reachable = true;
  try {
    const item = $(name).first();
    response = (item && item.json) ? item.json : null;
  } catch (e) {
    reachable = false;   // the reference threw
  }
  // ran is a claim about EXECUTION, not about whether the reference resolved. A stage that is not
  // on this path/mode did not run (free). Any OTHER stage is on the path and therefore RAN -- if we
  // could not read it, that is a lost meter (money spent, unmeasured), never a silent free zero.
  const on_path = !NOT_ON_PATH.has(name);
  const ran = on_path;
  // meter_lost is implied downstream when ran=true AND response has no usage; surface the custody
  // failure explicitly too, so a lost on-path meter is visible in THIS node, not only in the ledger.
  // v4.2.57: a row with NO provider is a code node — it buys no tokens, so "no usage block" is the
  // truth about it, not a lost meter. Declaring the hop at zero is an ASSERTION ("accounted for,
  // costs nothing") and is checked like any other: it must be reachable and it must stay at zero.
  // The alternative — leaving Verify out of the map — would have made a hop on the money path
  // invisible, which is the same silence rule 4 exists to forbid.
  const zero_by_construction = (provider == null);
  // v4.2.70: a stage that is NOT ON PATH is not a participant, and printing a model id beside it
  // implies it contributed. Twelve reports carried `| Stage 3 Grok | grok-4.5 | ... | _not run_ |`
  // and two readers took the row for a participant with an idle meter; the stage has had no
  // incoming or outgoing edge since before v4.2.44. The model id is suppressed for such rows —
  // a price-map constant is not evidence about what answered.
  const on_path_participant = on_path && !zero_by_construction;
  const meter_unreachable = (on_path && !zero_by_construction && (response == null || !reachable));
  stages.push({ stage: name, provider: (on_path ? provider : null),
                model: (on_path ? model : null),
                model_configured: model,          // kept for the drift watchdog, never printed
                disconnected: !on_path && provider != null,
                response, ran, meter_unreachable, zero_by_construction, reachable,
                on_path_participant });
}

// The model ids above are duplicated from each node's request body — n8n gives a Code node no way
// to read a sibling's parameters. That duplication is a KNOWN defect: change a model in a node
// body and this list goes stale silently, mispricing the run against the old model's rate. The
// guard: if a provider echoes the model it actually served, compare and flag the drift rather
// than trust the constant. Anthropic and OpenAI both echo `model`; Gemini/xAI/Perplexity vary.
// v4.2.70 (mandate б): the run DECLARES how many opinions actually formed it. The Grok stage was
// disconnected by an operator decision in 2026-07-18 — a correct decision — and for twelve runs
// nothing said the council had three members instead of four. The `_not run_` row was read twice
// by two people and seen by neither: attention lost again, so this becomes a mechanism.
const OPINION_STAGES = ['Stage 2a Claude', 'Stage 2b Claude', 'Stage 3 Grok', 'Stage 4 Gemini',
                        'Stage 5 Auditor', 'Stage 6 Arbiter'];
const _op = stages.filter(s => OPINION_STAGES.indexOf(s.stage) !== -1);
const council = {
  participated: _op.filter(s => s.on_path_participant).map(s => s.stage),
  absent: _op.filter(s => !s.on_path_participant)
             .map(s => ({ stage: s.stage, reason: (s.disconnected ? 'not wired into the graph'
                                                                  : 'not on this path/mode') })),
};
council.count = council.participated.length;
council.full_slate = (council.absent.length === 0);
const drift = [];
for (const s of stages) {
  const echoed = s.response && (s.response.model || s.response.modelVersion);
  if (echoed && typeof echoed === 'string' && s.model && echoed.indexOf(s.model) !== 0
      && s.model.indexOf(echoed) !== 0) {
    drift.push(s.stage + ': node body says ' + s.model + ', provider served ' + echoed);
    s.model_drift = echoed;
  }
}

// v4.2.18: carry the DI payload down the MAIN LINE. Assemble used to read $('Parse DI')
// directly — a hard throw on gated runs (Parse DI never executes) and a long-range
// reference besides. $input here IS Parse DI's output on full runs and Gated Verdict's
// on gated runs; two short hops from Assemble (proven-safe custody).
const di_payload = $input.first().json || null;
return [{ json: { council, stages, ticker: ($('Eligibility').first().json || {}).ticker || null,
                  di_payload,
                  model_drift: drift, collected_at: new Date().toISOString() } }];

// v4.2.17 REPRICE prep: assemble the /reprice body from the freshest dossier row.
// chat_id via $('Gather Data') — 2 hops, inside the proven-safe custody range.
const gd = $('Gather Data').first().json;
const row = $input.first().json || {};
const has_dossier = !!(row && row.ticker);
let result = {};
try { result = (typeof row.result_json === 'string') ? JSON.parse(row.result_json) : (row.result_json || {}); } catch(e) { result = {}; }
// spec_date: verdict date if present, else the row insert date — never invented.
const spec_date = row.verdict_date ? String(row.verdict_date).slice(0,10)
                : (row.added_at ? String(row.added_at).slice(0,10) : null);
return [{ json: { ticker: gd.ticker, chat_id: gd.chat_id, has_dossier,
  stored_verdict: row.verdict || null, spec_date, result } }];

// v4.2.17: render the reprice answer. English only (report-facing rule).
const prep = $('Reprice Prep').first().json;
const r = $input.first().json || {};
const t = prep.ticker;
let text;
if (!prep.has_dossier) {
  text = 'FILE: ' + t + ' — no dossier on record. Run a full analysis first (send `' + t + '`); `reprice ' + t + '` becomes available after it lands.';
} else if (!r.repriced) {
  const ref = r.refusal || {};
  const why = ref.reason || JSON.stringify(r._errors || r.error || 'unknown');
  let det = '';
  if (ref.reason === 'newer_filing_since_spec' && Array.isArray(ref.filings)) {
    det = '\n' + ref.filings.map(f => '- ' + f.form + ' filed ' + f.filingDate + ' (' + f.accession + ')').join('\n');
  }
  if (ref.reason === 'spec_stale_age') det = '\nSpec age: ' + ref.age_days + 'd (max ' + ref.max_age_days + 'd).';
  text = 'REFUSED: ' + t + ' reprice — ' + why + det + (ref.note ? '\n' + ref.note : '') + '\nRun a full analysis for a fresh verdict.';
} else {
  // LEG-OK: stored RESULT (legacy payloads); the verdict-leg ladder is preferred just below.
const ivb = r.ivc_base || {};
  // v4.2.40 (mandate II, SEVENTH defect of the leg class): the reprice card rendered the ladder
  // from ivc_base (GAAP leg) while the verdict follows the conservative leg. Same defect as the
  // main report (II.5): a fallback chain whose FIRST source is the wrong leg. RESULT.mos_ladder
  // is the verdict-leg ladder; ivc_base stays only as a fallback for older payloads.
  const ladderSrc = (r.mos_ladder && r.mos_ladder.length) ? r.mos_ladder : (ivb.mos_ladder || []);
  const ladderLegLbl = r.mos_ladder_leg ? ' (leg: ' + r.mos_ladder_leg + ')' : '';
  const rows = ladderSrc.map(l => '- MoS ' + l.mos_target_pct + '%: $' + l.buy_threshold_price + (l.reached ? ' REACHED' : ' (' + l.discount_to_current_pct + '% above)')).join('\n');
  const st_fail = r.self_tests && r.self_tests.identity_at_old_price_ok === false;
  text = 'REPRICE ' + t + ' (spec of ' + r.derived_from_spec_date + ', age ' + (r.spec_age_days != null ? r.spec_age_days + 'd' : 'n/a') + ')\n'
    + 'Price: $' + r.price_at_spec + ' -> $' + r.price_new + ' (' + (r.price_change_pct > 0 ? '+' : '') + r.price_change_pct + '%)\n'
    + 'Implied CAGR: ' + (ivb.implied_cagr_pct != null ? ivb.implied_cagr_pct + '%' : 'n/a')
    + ' | MoS: ' + (ivb.mos_pct != null ? ivb.mos_pct + '%' : 'n/a') + '\n'
    + 'Verdict cap: ' + r.verdict_cap + (r.verdict_cap_changed ? ' *** CHANGED (was ' + r.stored_verdict_cap + ') ***' : ' (unchanged)') + '\n'
    + rows
    + (st_fail ? '\nSELF-TEST FAILED: identity_at_old_price — do NOT trust this rescale.' : '')
    + '\nRescale only: assumptions, IV and thresholds are frozen at spec date. Not a fresh analysis.';
}
return [{ json: { chat_id: prep.chat_id, text } }];

// v4.2.18 GATED verdict (BACKLOG #6). Emits the exact Parse DI shape so Collect Usage,
// Cost Ledger and Assemble need no special casing. Honesty rules:
//  - di is NULL, not 0 — the adversarial chain did not run, so there IS no disagreement
//    measurement (zero is not unknown, v4.2.8 lesson);
//  - final_verdict is the DETERMINISTIC verdict_cap from RESULT, never an invented arbiter
//    verdict; if it is missing, it stays null and says so.
const pv = $input.first().json;  // Parse Verdict payload, passed through two IFs
let cap = null;
try {
  const dp = $('Build Radar').first().json.dossier_passthrough || {};
  cap = (dp.result_json && dp.result_json.verdict_cap) || null;
} catch(e) { cap = null; }
return [{ json: { di: null, di_class: 'GATED', final_verdict: cap, flip: false,
  contested: false, di_llm: null, di_source: 'gated_run_stage5_6_skipped',
  di_divergence: false,
  di_driver_note: 'gated run — Stage 5/6 skipped by design; the verdict shown is the deterministic verdict_cap. Run `TICKER full` for the adversarial chain.',
  chat_id: pv.chat_id, ticker: pv.ticker } }];

// v4.2.57 — ENTITY GATE. Deterministic, thin, and placed where a refusal is still possible.
// WHY THIS NODE EXISTS: Stage 1 was handed the bare string "MA" and resolved it to the Commonwealth
// of Massachusetts on 2026-07-24 and on both 2026-07-31 runs. The whole qualitative layer came back
// about a US state. Every memo NOTICED and tagged the sections [UNVERIFIED] — and the run proceeded
// anyway, because detection is not refusal. Eight days, three runs, no stop. The graph had no point
// at which a FACT_PACK could be rejected: nine consumers read Stage 1 directly, by name.
// SCOPE IS DELIBERATELY ONE THING: parse the echo, compare the CIK, pass or refuse. No scoring, no
// repair, no partial credit. Identity is not a matter of degree.
const raw = $input.first().json;
let text = ''; try { text = raw.choices[0].message.content || ''; } catch (e) { text = ''; }
const gt = (() => { try { return $('Eligibility').first().json._edgar || {}; } catch (e) { return {}; } })();
// Compare CIKs as NUMBERS, not strings: SEC writes 0001141391, humans and models write 1141391.
const norm = (s) => String(s == null ? '' : s).replace(/\D/g, '').replace(/^0+/, '');
const gtCik = norm(gt.cik);
const ticker = (() => { try { return $('Eligibility').first().json.ticker || '?'; } catch (e) { return '?'; } })();
const m = text.match(/RESOLVED_ENTITY\s*:\s*(.+?)\s*\(\s*CIK\s*([0-9]{1,10})\s*\)/i);
if (!gtCik) {
  throw new Error('FACTPACK_ENTITY_UNVERIFIED: GROUND_TRUTH carries no CIK for ' + ticker
    + ', so the FACT_PACK entity cannot be verified against anything. Refusing before judgment.');
}
if (!m) {
  throw new Error('FACTPACK_ENTITY_UNVERIFIED: the FACT_PACK did not open with the required'
    + ' `RESOLVED_ENTITY: <name> (CIK <cik>)` line, so which company it describes is unknown.'
    + ' Expected CIK ' + gtCik + ' (' + ticker + '). Refusing before judgment.');
}
const echoed = norm(m[2]);
if (echoed !== gtCik) {
  throw new Error('FACTPACK_ENTITY_MISMATCH: the FACT_PACK describes CIK ' + echoed + ' ("'
    + String(m[1]).slice(0, 80) + '") but GROUND_TRUTH resolved ' + ticker + ' to CIK ' + gtCik
    + (gt.entity_name ? ' (' + gt.entity_name + ')' : '') + '. Refusing before judgment.');
}
// Verified. From here the node does ONE more thing, and it is a measurement, not an edit:
// count how much of the FACT_PACK came back empty.
//
// WHY HERE. The counter first shipped inside Assemble Report — and Assemble Report is one of TWO
// terminal assemblers. The CBRS and SMR runs of 2026-08-02 both routed to Core-V and carried NO
// vector line, while carrying 32 and 46 [UNVERIFIED] tags: the names that most needed the count
// were the ones structurally unable to receive it. Two further properties follow from moving it
// here: a renderer no longer computes what it publishes, and a THIRD assembler added later
// inherits the field instead of silently omitting it. The count is a fact about the FACT_PACK,
// so it belongs where the FACT_PACK is examined, not where it is printed.
//
// Count VECTORS (sections), not occurrences: the raw tag count does not separate the cases —
// MA run2 (entity substituted) carried 14 tags, NFLX (entity clean) carried 10. The ratio does.
// CALIBRATION — PROVISIONAL, n=4 with ONE clean observation:
//   MA 24.07 18/31 = 58% | MA 31.07 r1 13/34 = 38% | MA 31.07 r2 13/34 = 38% | NFLX 24.07 6/38 = 16%
// 30% clears the clean run by 14pp and catches all three contaminated ones by 8pp. A calibration
// on thin data, NOT a measured constant — the label travels WITH the field so no reader a month
// from now mistakes 30% for something that was derived. Recalibrate at the six-clean-run review.
const FP_THRESHOLD = 0.30;
// The chunk BEFORE the first heading is the preamble (the RESOLVED_ENTITY line and any framing).
// It is not a fact vector, and counting it would both inflate the denominator and diverge from the
// calibration above, which was measured over headed sections only. Keep only chunks that ARE
// sections — the denominator has to mean the same thing here as it did when 30% was chosen.
// v4.2.76 (mandate a): count LEAVES, not containers. The ORCL diagnostic reported "4 live of 19"
// and three of those four were headings whose own paragraph carried no [UNVERIFIED] marker while
// both sub-sections under them were dead. A container inherits nothing from its children, so it
// looked alive by construction. Every measurement taken with the old rule — including the 6/25
// baseline this diagnostic was compared against — was inflated the same way, which is why the
// comparison found "no change": both sides were wrong in the same direction.
// A leaf is a section with no deeper heading beneath it before the next section of its own level.
const _all = String(text).split(/\n(?=#{1,4}\s)/).filter(s => /^#{1,4}\s/.test(s));
const _lvl = (s) => (s.match(/^(#{1,4})/) || ['',''])[1].length;
