if (_cl2 && !_cl2.full_slate) {
  M.push('- **Оценка построена на ' + _cl2.count + ' мнениях из ' + (_cl2.count + _cl2.absent.length)
       + '.** Не участвовали: ' + _cl2.absent.map(a => a.stage).join(', ')
       + '. Это не сбой прогона, но состав консилиума был неполным.');
}
// v4.2.69 (mandate 3): the single-leg state reaches the human document too. It changes how much
// weight the verdict carries, so it belongs where the verdict is read, not only in the machine file.
if (!res.dual_basis) {
  const _slf = (res.flags || []).filter(f => String(f).indexOf('SINGLE_LEG_RUN') === 0)[0];
  M.push('- **Оценка построена по одному основанию, а не по двум.** Обычно мы считаем стоимость '
       + 'дважды — от прибыли и от денежного потока — и берём осторожнейший из двух ответов. '
       + 'В этом прогоне вторая оценка не построилась' + (_slf ? ', причина: ' + _slf.replace(/^SINGLE_LEG_RUN: /,'').replace(/\s*$/,'') : '')
       + '. Перекрёстной проверки у этой оценки нет.');
}
// v4.2.73: the old summary line duplicated the caveat below in acceptance language. The caveat
// says the same thing split by KIND of data, which is the distinction that matters to a reader;
// the raw ratio stays in the machine report, where an auditor wants it.
if (!fpv) M.push('- Полнота внешних данных этого прогона не измерена — сообщите об этом дефекте.');
// v4.2.73 (architect, 03.08.2026): the old wording — "разделов с непроверенными данными: 19 из 25
// (76%) — качество данных под вопросом" — was written in the language of internal acceptance and
// read as "do not trust this report", while the numbers that decide the verdict were complete and
// verified. Two different things were being marked with one label. Separated:
M.push('- **Расчётные данные (отчётность SEC): полные и проверенные.** Оценка стоимости, лестница '
     + 'входа и доходность опираются только на них.');
if (fpv && fpv.total) {
  const _live = fpv.total - fpv.unverified;
  M.push('- **Новостной контекст: собрано ' + _live + ' разделов из ' + fpv.total + '.** '
       + (fpv.data_questionable
          ? 'Балл качества бизнеса опирается на неполную картину — регуляторика, конкуренты '
            + 'и реакция рынка собраны частично. **Оценка стоимости этим не затронута.**'
          : 'Картина по внешним источникам собрана в основном полно.'));
}
M.push('- Оценка сделана на цене ' + money(price) + '. При изменении цены пересчитывается доходность, но не стоимость компании.');
M.push('');
M.push('---');
M.push('---');
M.push('');
M.push('# ПРИЛОЖЕНИЕ · для тех, кто хочет разобраться');
M.push('');
M.push('## Расчёт по шагам, числами');
M.push('');
M.push('| шаг | значение |');
M.push('| --- | --- |');
M.push('| отправная точка на акцию | ' + money(pub.base_per_share != null ? pub.base_per_share : inp.base_per_share) + ' |');
M.push('| темп роста (меньшая из оценок за 3 и 5 лет) | ' + pc(inp.g) + ' |');
M.push('| размывание доли | ' + pc(inp.dilution_cagr) + ' |');
M.push('| прибыль десятого года с поправкой на выкуп | ' + money(ivb.eps_terminal_dilution_adj) + ' |');
M.push('| × выходной множитель ' + n2(inp.future_pe,0) + ' | ' + money(ivb.fv10_per_share) + ' |');
M.push('| ÷ 1.12¹⁰ | **' + money(IV) + '** |');
M.push('');
if (cl.iv != null) {
  M.push('### Обе оценки одним расчётом');
  M.push('');
  M.push('| шаг | осторожная | центральная |');
  M.push('| --- | --- | --- |');
  // v4.2.71 (mandate 3): the BASE row. On META the two lenses ran on 17.91 and 23.49 per share —
  // the single largest contributor to an 85.7% gap — and the table listed only growth and the
  // multiple. A comparison table that omits the biggest difference is not a comparison.
  const _cbase = (cl.computed_on === 'gaap_base' && db.gaap_eps) ? db.gaap_eps.base_per_share : null;
  const _vbase = (pub.base_per_share != null) ? pub.base_per_share : inp.base_per_share;
  if (_cbase != null && _vbase != null && Math.abs(_cbase - _vbase) > 1e-9) {
    M.push('| отправная точка на акцию | ' + money(_vbase) + ' | ' + money(_cbase) + ' |');
  }
  M.push('| темп роста | ' + pc(inp.g) + ' | ' + pc(cl.growth_used) + ' |');
  M.push('| множитель | ' + n2(inp.future_pe,0) + ' | ' + n2(cl.future_pe_used,2) + ' |');
  M.push('| **оценка** | **' + money(IV) + '** | **' + money(cl.iv) + '** |');
  M.push('');
  // v4.2.69 — the sentence is BUILT, not stored. The stored version claimed "exactly two
  // decisions: growth and the ceiling" on every name. On META the ceiling contributed zero; on
  // ORCL the ceiling AND the base contributed zero and the whole gap was growth — while the
  // sentence still asserted two factors and "nothing else differs". A statement about numbers,
  // written once and printed beside numbers that contradict it, is the third instance of the
  // lensrender class: the fix reached the computation and not the prose. Now the prose reads the
  // same field the numbers come from, so it cannot drift from them.
  const _d = cl.gap_decomposition || null;
  const _dir = (cl.delta_iv_vs_verdict_pct != null && cl.delta_iv_vs_verdict_pct < 0)
    ? 'ниже' : 'выше';
  if (_d) {
    const _f = [];
    if (_d.growth_change) _f.push({ k: 'темп роста', v: _d.growth_change });
    if (_d.multiple_change) _f.push({ k: 'выходной множитель', v: _d.multiple_change });
    if (_d.base_change) _f.push({ k: 'база расчёта', v: _d.base_change });
    _f.sort((a, b2) => Math.abs(b2.v) - Math.abs(a.v));
    if (!_f.length) {
      M.push('Оценки совпали: ни одно из страховочных допущений на этом имени не сработало.');
    } else {
      M.push('Центральная оценка **' + _dir + '** осторожной на **'
        + n2(Math.abs(cl.delta_iv_vs_verdict_pct), 1) + '%**. Что именно её двигает:');
      M.push('');
      M.push('| что различается | на сколько меняет оценку |');
      M.push('| --- | --- |');
      for (const x of _f) M.push('| ' + x.k + ' | ' + (x.v > 0 ? '+' : '') + money(x.v) + ' |');
      M.push('');
      const _zero = [];
      if (!_d.multiple_change) _zero.push('выходной множитель');
      if (!_d.base_change) _zero.push('база расчёта');
      if (_zero.length) {
        M.push('Остальное между оценками совпадает: ' + _zero.join(', ')
          + ' — одинаковы, вклад нулевой.');
        M.push('');
      }
      M.push('*Величины не складываются в общую разницу: факторы действуют одновременно '
        + 'и усиливают друг друга.*');
      if (_dir === 'ниже') {
        M.push('');
        M.push('**Здесь редкий случай: центральная оценка НИЖЕ осторожной.** Медианный темп роста '
          + 'оказался скромнее оценки по крайним точкам — выручка росла неравномерно, и медиана '
          + 'сгладила удачные годы. Вердикт по-прежнему выносится по осторожной оценке.');
      }
    }
  } else {
    M.push('*Разложение расхождения этим прогоном не получено — сообщите об этом дефекте.*');
  }
  M.push('');
}
if (res.year5_reference != null) {
  M.push('## Справочная точка на пятом году');
  M.push('');
  M.push('**' + money(res.year5_reference) + '**');
  M.push('');
  M.push('*Справочная точка. Вердикт выносится по десятилетнему горизонту: пятилетний расчёт '
       + 'обрывает траекторию до затухания и потому систематически оптимистичнее.*');
  M.push('');
}
// v4.2.71: the appendix of the approved spec — the six-step calculation with prose, the score
// breakdown and the glossary. The live brief shipped a bare table: a reader who wanted to check
// the arithmetic had the numbers and none of the reasoning that turns them into a calculation.
M.push('### Что здесь произошло, по шагам');
M.push('');
M.push('1. **Отправная точка.** Берём прибыль (или денежный поток) на акцию за последний год — '
  + money(pub.base_per_share != null ? pub.base_per_share : inp.base_per_share)
  + '. Это факт из отчётности, не прогноз.');
M.push('2. **Траектория.** Наращиваем её на ' + pc(inp.g) + ' в год — темп, который компания '
  + 'реально показывала. Полный темп держится пять лет, затем плавно снижается к '
  + pc(inp.terminal_g) + ' к десятому году.');
M.push('3. **Поправка на акции.** Число акций меняется на ' + pc(inp.dilution_cagr)
  + ' в год' + ((inp.dilution_cagr != null && inp.dilution_cagr < 0) ? ' — компания выкупает акции, '
  + 'поэтому на каждую оставшуюся приходится больше' : ' — доля акционера размывается') + '.');
M.push('4. **Стоимость через десять лет.** Прибыль десятого года ' + money(ivb.eps_terminal_dilution_adj)
  + ' умножаем на выходной множитель ' + n2(inp.future_pe, 0) + ' — получается '
  + money(ivb.fv10_per_share) + '.');
M.push('5. **Приведение к сегодня.** Делим на 1.12 десять раз, потому что нам нужны 12% годовых. '
  + 'Получается ' + money(IV) + ' — цена, при которой покупка даёт ровно 12% и ни центом больше.');
M.push('6. **Лестница.** Из неё вычитаем запас прочности — это и есть цена покупки.');
M.push('');
M.push('**Чего мы НЕ делаем:** не прогнозируем цену акции, не используем прогнозы аналитиков '
  + 'как вход, не подставляем оптимистичные допущения. Все числа приходят из отчётности, '
  + 'поданной в SEC.');
M.push('');
if ((gps.blocks || []).length) {
  M.push('## Из чего сложились баллы');
  M.push('');
  M.push('| сторона | балл | максимум |');
  M.push('| --- | --- | --- |');
  for (const bl of gps.blocks) {
    const ru = BLOCK_RU[bl.name || bl.block] || [bl.name || bl.block, ''];
    M.push('| ' + ru[0] + ' | ' + bl.points + ' | ' + bl.max + ' |');
  }
  M.push('| **Итого** | **' + n2(gps.total, 0) + '** | **'
    + (gps.max != null ? n2(gps.max, 0) : '—') + '** |');
  M.push('');
}
M.push('## Словарь');
M.push('');
M.push('| термин | что означает |');
M.push('| --- | --- |');
for (const g2 of GLOSSARY) M.push('| ' + g2[0] + ' | ' + g2[1] + ' |');
M.push('');
M.push('## Источники');
M.push('');
M.push('| данные | источник |');
M.push('| --- | --- |');
M.push('| отчётность | SEC EDGAR, ' + company + ', CIK ' + ((((el._edgar)||{}).cik) || '—') + ' |');
M.push('| цена и история цен | Tiingo, скорректированные цены закрытия |');
M.push('| снимок цены | ' + money(price) + ' |');
M.push('| безрисковая ставка | FRED DGS10 |');
M.push('');
M.push('---');
M.push('');
M.push('> **Правило выдачи.** Выход прогона — пара документов: эта записка и машинный отчёт. '
     + 'Доставка обоих — обязательная часть публикации.');
M.push('');
M.push('*Записка сформирована автоматически из отчётности SEC. Не является инвестиционной рекомендацией.*');

// v4.2.66: emit the same shape Send Report consumes — json for the caption, binary for the file.
// The v4.2.65 version returned only `brief_md` and had NO outgoing connection: the document was
// assembled and thrown away. That is `lensrender-01` again, on the newest surface and one step
// further downstream — the render reached the markdown, and the markdown reached nobody. The
// earlier pins could not see it: they все asserted on the rendered string, and the string was fine.
const chat_id = el.chat_id;
const fname = ticker + '_' + date.replace(/-/g,'') + '_ЗАПИСКА.md';
const brief_md = M.join('\n');
return [{ json: { chat_id, ticker, brief_ok: true, brief_md,
  doc_kind: 'investor_brief',
  // The pair contract, carried in the payload so a downstream reader can check it without
  // knowing the graph: this run owes TWO documents, and this is one of them.
  pair_contract: { expects: ['machine_report', 'investor_brief'], this_one: 'investor_brief' } },
  binary: { data: { data: Buffer.from(brief_md,'utf8').toString('base64'),
                    mimeType: 'text/markdown', fileName: fname } } }];

