// === Merge FACT_PACK Calls — thin, deterministic, and it decides nothing. ===
// v4.2.74. One search covering eleven unrelated topics returned snippets for two or three of them;
// the model tagged the rest [UNVERIFIED] honestly ("not visible in this interface"). The request
// was split into four topical calls, each carrying the FULL contract plus a focus line — four
// slightly different contracts would have been worse than one starved search.
//
// This node reassembles them into ONE payload shaped exactly like the single call it replaces, so
// the entity gate and the nine downstream consumers cannot tell a section from call #3 from a
// section from call #1. That indistinguishability IS the contract; if it breaks, the split has
// quietly become four pipelines.
// v4.2.75 — THE CALLS RUN IN SERIES, not in parallel. The first live run of the split reported
// three of four themes as SOURCE_CALL_FAILED, and the failure signature was exactly the branch
// order: `fin` (first branch) succeeded, the other three "returned nothing". They had not run.
// Four edges into ONE input of a Code node is a fan-in n8n does not wait on — the node fires when
// the first branch arrives, and `$('Stage 1 FP legal')` throws because that node has no output
// yet. My own failure handling then reported an unreachable SOURCE, which was true of the moment
// and false about the world: the call was not dead, it was not yet born.
// Chained execution costs latency (four sequential HTTP calls instead of four parallel ones) and
// buys correctness. n8n's own Merge node waits, but takes at most two inputs by default and would
// need three of them stacked — more machinery than a chain, for the same result.
// v4.2.77 - THREE calls, not four. `fin` asked search for tables the pipeline computes itself
// (EPS series, medians, consensus, peer multiples); the search could not find OUR numbers in
// articles and the refusals were recorded as incompleteness of the run. Tier A took that content,
// and the residue of `fin` - the reported quarter, guidance, backlog - is a dated news event and
// lives in `news`. The row for `fin` is DELETED from the meter map in the same changeset: a stage
// that no longer exists must not sit next to not_run, wearing the look of a free zero.
const CALLS = ['Stage 1 FP legal', 'Stage 1 FP compete', 'Stage 1 FP news'];
const SKIP = '[NOT REQUESTED IN THIS CALL]';

const parts = [], failed = [], seen = {}, collisions = [];
for (const name of CALLS) {
  let txt = null;
  try { txt = $(name).first().json.choices[0].message.content; } catch (e) { txt = null; }
  if (typeof txt !== 'string' || !txt.trim()) {
    // A theme that failed is NOT a theme that found nothing. Its sections are marked so the
    // difference survives into the report: an unreachable source is an engineering event, an empty
    // search is a fact about the world, and one must never be published as the other.
    failed.push(name);
    parts.push('## SOURCE_CALL_FAILED: ' + name + '\n\nThe search call for this theme did not '
      + 'return usable content. Its sections are [UNVERIFIED] because the SOURCE was unreachable, '
      + 'not because the facts were absent.\n');
    continue;
  }
  // Sections this call was told not to cover are dropped whole: leaving the marker in would put
  // the phrase in front of the reader and make an unasked section look like a missing one.
  const kept = txt.split(/\n(?=#{2,4}\s)/).filter(s => s.indexOf(SKIP) === -1);
  for (const sec of kept) {
    const h = (sec.match(/^#{2,4}\s+(.+)$/m) || [])[1];
    if (h) {
      const key = h.trim().toLowerCase();
      // Two calls answering the SAME section is a contract defect: one of them was told not to.
      // Picking a winner silently would publish an arbitrary choice as a fact — the section is
      // refused instead, loudly, and the run survives.
      if (seen[key]) { collisions.push(h.trim()); continue; }
      seen[key] = name;
    }
    parts.push(sec);
  }
}

let merged = parts.join('\n');
if (collisions.length) {
  merged = '## MERGE_COLLISION\n\nThese sections were answered by more than one themed call and '
    + 'are therefore REFUSED rather than arbitrated: ' + collisions.join('; ')
    + '. Treat them as [UNVERIFIED].\n\n' + merged;
}

// Shaped exactly like the single Perplexity response it replaces — same path, same field names.
return [{ json: { choices: [{ message: { content: merged } }],
  _fp_merge: { calls: CALLS.length, failed: failed, collisions: collisions,
               sections: Object.keys(seen).length } } }];
